  const flag = one(nodes(task), n => ts.isVariableDeclaration(n) && n.name.getText(ast) === "hasTaskTitle", "one pure title predicate");
  assert.equal(flag.initializer.getText(ast), 'typeof taskTitle === "string" && taskTitle.trim().length > 0');
  const header = one(nodes(task), n => ts.isJsxElement(n) && n.openingElement.attributes.properties.some(a =>
    ts.isJsxAttribute(a) && a.name.getText(ast) === "data-task-review-brief" && a.initializer?.text === "true"), "one existing header marker");
